// mkv3-apollonian.ts — STRUCTURES LANE struct-180, Round 11 commission R11-12
// THE APOLLONIAN GASKET: the kissing-circle rose window.
//
// ONE IDEA: THE STONE DISC THE SKY PACKS. Descartes 1643 / Soddy 1936: the
// (−1,2,2,3) integer gasket generated by recursive Descartes replacement
// (struct180-probe-apollonian.ts, ALL CHECKS PASS — 34 holes k≤45, every
// curvature an integer, zero overlaps, both mirror symmetries, min stone
// bridge 0.027 m). A great stone disc PIERCED by the packing: the two
// kissing halves (k=2) as the tall lancets, the seed k=3 left and its
// PARABOLIC TWIN right (the packing's hidden fourth — same curvature,
// reflected center; the double root in curvature is still TWO circles),
// generations of ever-smaller integer circles descending to the cutoff.
// Sky completes the packing. ONE brass ember floats in the twin's hole.
//
// KIN CHECK (elevates, never competes): no standing form is a circle
// packing (ledger grep apollonian/soddy/gasket/descartes: 0/0/0). The
// mosaic gallery rings own the ANNULUS; the orreryring owns ORBIT chart
// rings; this owns the TANGENT-KISS lattice — circles that TOUCH, the
// Soddy "Kiss Precise" lineage. Nearest kin by feel: the pierced rose
// window reads against the sky like nothing else on the avenue.
//
// WORLD MAP (probe C7 laws): gasket R 2.05 in a stone ring RIM 0.35 → disc
// R 2.40, thickness 0.40; chunky plinth 2.80 × 0.70 × 0.90 with the disc
// arc SEATED 0.12 into it (the honest embed — the bottom lobe is
// rim-tangent by theorem, so no lintel band exists; the seat + ring are the
// grounding). Envelope 4.80 × 5.58 × 0.70, symmetric, origin-centered.
// Folly class, no walk owed (catalan/clebsch/menger precedent).
//
// LAWS HONORED (struct-121+ lineage): texMat lanes (struct-38) — apollo_
// stone cell 32 (the sierpinski/menger mottle calibration: per-pixel grain
// averages flat at 18m); bead emissive 0x9a7030 @ 1.0 in-GLB (dusk lineage,
// no light entity); glow census exactly 1 KEEP (glow_ap_1); NaN 0; nodes
// 1 bucket + 1 KEEP = 2. Deterministic: generated geometry + seeded texMat.
import * as THREE from "three";
import { toGLB, texMat } from "./glbwrite.ts";
import { mergeByMaterial } from "./mergekit.ts";
import { writeFileSync } from "node:fs";

// ---- constants (ONE CONTRACT with the probe — copied from struct180-probe) --------------------------
const R_W = 2.05;                       // gasket world radius
const RIM = 0.35;                       // stone ring width
const TH = 0.40;                        // disc thickness
const PL_H = 0.90, PL_W = 2.80, PL_D = 0.70;
const SINK = 0.12;                      // disc arc seated into plinth top
const KMAX = 45;
const DISC_R = R_W + RIM;               // 2.40
const Y_CENTER = PL_H - SINK + DISC_R;  // 3.18 — disc center height

// ---- regenerate the packing (probe chassis verbatim, trimmed to output) -----------------------------
type Cx = { re: number; im: number };
const cAdd = (a: Cx, b: Cx): Cx => ({ re: a.re + b.re, im: a.im + b.im });
const cMul = (a: Cx, b: Cx): Cx => ({ re: a.re * b.re - a.im * b.im, im: a.re * b.im + a.im * b.re });
const cScale = (a: Cx, s: number): Cx => ({ re: a.re * s, im: a.im * s });
const cAbs = (a: Cx): number => Math.hypot(a.re, a.im);
const cSqrt = (a: Cx): Cx => {
    const m = cAbs(a), t = Math.sqrt(Math.max(0, (m + a.re) / 2));
    return { re: t, im: (a.im === 0 && a.re < 0) ? 0 : (a.im >= 0 ? 1 : -1) * Math.sqrt(Math.max(0, (m - a.re) / 2)) };
};
type Cir = { k: number; x: number; y: number };
const rad = (c: Cir) => 1 / Math.abs(c.k);
const dist = (a: Cir, b: Cir) => Math.hypot(a.x - b.x, a.y - b.y);
const tangentGap = (a: Cir, b: Cir): number => {
    const d = dist(a, b);
    return a.k < 0 || b.k < 0 ? d - Math.abs(rad(a) - rad(b)) : d - (rad(a) + rad(b));
};
const kRoots = (k1: number, k2: number, k3: number): [number, number] => {
    const s = k1 + k2 + k3, r = 2 * Math.sqrt(Math.max(0, k1 * k2 + k2 * k3 + k3 * k1));
    return [s + r, s - r];
};
const zCandidates = (q: Cir[], idx: number, k4: number): Cir[] => {
    const others = q.filter((_, i) => i !== idx);
    const kzs = others.map(c => cScale({ re: c.x, im: c.y }, c.k));
    let sum = kzs[0];
    for (let i = 1; i < 3; i++) sum = cAdd(sum, kzs[i]);
    let acc = cMul(kzs[0], kzs[1]);
    acc = cAdd(acc, cMul(kzs[1], kzs[2]));
    acc = cAdd(acc, cMul(kzs[2], kzs[0]));
    const out: Cir[] = [];
    for (const sign of [1, -1]) {
        const kz4 = cAdd(sum, cScale(cSqrt(acc), 2 * sign));
        out.push({ k: k4, x: kz4.re / k4, y: kz4.im / k4 });
    }
    return out;
};

// rose-window orientation: halves top/bottom, seed k=3 LEFT, twin RIGHT
const seed: Cir[] = [
    { k: -1, x: 0, y: 0 },
    { k: 2, x: 0, y: 0.5 },
    { k: 2, x: 0, y: -0.5 },
    { k: 3, x: -2 / 3, y: 0 },
];
const key = (c: Cir) => `${c.k.toFixed(6)}@${c.x.toFixed(6)},${c.y.toFixed(6)}`;
const holes: Cir[] = [seed[1], seed[2], seed[3]];
const seen = new Set<string>(seed.map(key));
const quads: Cir[][] = [seed];
const quadSeen = new Set<string>([seed.map(key).sort().join("|")]);
let twin: Cir | null = null;
let pops = 0;
while (quads.length) {
    const q = quads.shift()!;
    if (++pops > 5000) throw Error("BFS bound exceeded");
    for (let i = 0; i < 4; i++) {
        const ki = q[i].k;
        const others = q.filter((_, j) => j !== i);
        const [r1, r2] = kRoots(others[0].k, others[1].k, others[2].k);
        let k4: number | null = null;
        if (Math.abs(r1 - ki) < 1e-12 && Math.abs(r2 - ki) < 1e-12) k4 = ki;
        else if (Math.abs(r1 - ki) < 1e-12) k4 = r2;
        else if (Math.abs(r2 - ki) < 1e-12) k4 = r1;
        else continue;
        if (k4 < 0.5 || k4 > KMAX + 1e-9) continue;
        const cands = zCandidates(q, i, k4);
        const c = dist(cands[0], q[i]) > dist(cands[1], q[i]) ? cands[0] : cands[1];
        let tg = 0;
        for (const o of others) tg = Math.max(tg, Math.abs(tangentGap(c, o)));
        if (tg > 1e-6 || Math.hypot(c.x, c.y) + rad(c) > 1 + 1e-9) continue;
        if (q === seed && k4 === ki) twin = c;          // the parabolic twin
        const kk = key(c);
        if (!seen.has(kk)) { seen.add(kk); holes.push(c); }
        const nq = [...q]; nq[i] = c;
        const qk = nq.map(x => key(x)).sort().join("|");
        if (!quadSeen.has(qk) && nq.every(x => x.k < 0 || x.k <= KMAX + 1e-9)) { quadSeen.add(qk); quads.push(nq); }
    }
}
if (holes.length !== 34) throw Error(`hole census ${holes.length} != 34 (probe contract)`);
if (!twin || twin.k !== 3) throw Error("twin not captured");
console.log(`packing: ${holes.length} holes k<=${KMAX}, twin at gasket (${twin.x.toFixed(4)},${twin.y.toFixed(4)})`);

// lip law (probe C6 verbatim): clamp(0.10·r_w, 0.013, 0.022)
const lipOf = (c: Cir) => Math.min(0.022, Math.max(0.013, 0.10 * (R_W / c.k)));

// ---- materials --------------------------------------------------------------------------------------
const stoneTex = texMat("apollo_stone", [0x6f6a60, 0x777166, 0x67625a], { rough: 0.95, scale: 2, weights: [3, 1, 1], cell: 32, seed: 9642 });

// ---- build ------------------------------------------------------------------------------------------
const g = new THREE.Group();

// the pierced disc: shape = gasket plane (x right, y up), extrude +Z, then
// rotate so the disc normal is world X (the window faces the walk; final yaw
// set at placement, oblique law struct-104).
{
    const shape = new THREE.Shape();
    shape.absarc(0, 0, DISC_R, 0, Math.PI * 2, false);
    let holeTotal = 0;
    for (const c of holes) {
        const r = R_W / c.k - lipOf(c);
        if (r <= 0.005) continue;
        const p = new THREE.Path();
        p.absarc(c.x * R_W, c.y * R_W, r, 0, Math.PI * 2, true);
        shape.holes.push(p);
        holeTotal++;
    }
    if (holeTotal !== 34) throw Error(`pierced holes ${holeTotal} != 34`);
    const disc = new THREE.Mesh(new THREE.ExtrudeGeometry(shape, {
        depth: TH, bevelEnabled: false, curveSegments: 48, steps: 1,
    }), stoneTex);
    disc.geometry.translate(0, 0, -TH / 2);        // center on the normal axis
    disc.rotation.y = Math.PI / 2;                  // normal +Z -> +X; shape +X -> -Z
    disc.position.y = Y_CENTER;
    g.add(disc);
    console.log(`disc: R ${DISC_R} t ${TH}, ${holeTotal} piercings, center y ${Y_CENTER}`);
}

// the plinth (chunky base wall segment, disc arc seated SINK into it)
{
    const plinth = new THREE.Mesh(new THREE.BoxGeometry(PL_D, PL_H, PL_W), stoneTex);
    plinth.position.set(0, PL_H / 2, 0);
    g.add(plinth);
    console.log(`plinth: ${PL_W}x${PL_D} h ${PL_H}; disc arc seated ${SINK} m`);
}

// the twin bead (glow KEEP, parabolic twin's center — the packing's hidden fourth)
const glowMeshes: THREE.Mesh[] = [];
{
    const bead = new THREE.Mesh(new THREE.SphereGeometry(0.09, 14, 12),
        (() => {
            const m = new THREE.MeshStandardMaterial({ color: 0xa8823f, roughness: 0.45, metalness: 0.75 });
            (m as any).emissive = new THREE.Color(0x9a7030);
            (m as any).emissiveIntensity = 1.0;      // dusk lineage (struct-82 law)
            return m;
        })());
    // gasket (2/3, 0) -> shape (1.3667, 3.18) -> world (x 0, y 3.18, z -1.3667)
    bead.position.set(0, Y_CENTER, -(2 / 3) * R_W);
    bead.name = "glow_ap_1";
    glowMeshes.push(bead);
    g.add(bead);
    const holeR = R_W / 3 - lipOf({ k: 3, x: 0, y: 0 });
    if (holeR - 0.09 < 0.30) throw Error(`bead clearance ${holeR - 0.09} < 0.30`);
    console.log(`twin bead: r 0.09 at (0, ${Y_CENTER}, ${(-(2 / 3) * R_W).toFixed(4)}), ${((holeR - 0.09)).toFixed(3)} m clear`);
}

// ---- census + envelope/NaN laws ---------------------------------------------------------------------
{
    if (glowMeshes.length !== 1) throw Error(`glow census ${glowMeshes.length} != 1`);
    const env = new THREE.Box3().setFromObject(g);
    const sz = env.getSize(new THREE.Vector3());
    if (env.min.y < -1e-6) throw Error(`below grade ${env.min.y}`);
    const expD_x = Math.max(TH, PL_D), expW_z = Math.max(2 * DISC_R, PL_W), expH = (PL_H - SINK) + 2 * DISC_R;
    if (Math.abs(sz.x - expD_x) > 0.02 || Math.abs(sz.y - expH) > 0.05 || Math.abs(sz.z - expW_z) > 0.02)
        throw Error(`envelope ${sz.x.toFixed(2)}x${sz.y.toFixed(2)}x${sz.z.toFixed(2)} != ${expD_x.toFixed(2)}x${expH.toFixed(2)}x${expW_z.toFixed(2)} (x=depth, z=width — disc faces ±X)`);
    // symmetric on x/z (origin-centered SAT lawful)
    if (Math.abs(env.min.x + env.max.x) > 0.01 || Math.abs(env.min.z + env.max.z) > 0.01)
        throw Error(`envelope not origin-centered: x[${env.min.x.toFixed(3)},${env.max.x.toFixed(3)}] z[${env.min.z.toFixed(3)},${env.max.z.toFixed(3)}]`);
    let nan = 0;
    g.traverse((o: any) => {
        const mesh = o as THREE.Mesh;
        if (!mesh.isMesh) return;
        const posA = mesh.geometry.getAttribute("position") as THREE.BufferAttribute;
        for (let i = 0; i < posA.count; i++) if ([posA.getX(i), posA.getY(i), posA.getZ(i)].some(isNaN)) nan++;
    });
    if (nan) throw Error(`${nan} NaN vertices`);
    const meshes = g.children.filter((o) => (o as THREE.Mesh).isMesh).length;
    console.log(`envelope OK: ${sz.x.toFixed(2)}x${sz.y.toFixed(2)}x${sz.z.toFixed(2)} y[${env.min.y.toFixed(3)}..${env.max.y.toFixed(3)}], pre-merge meshes ${meshes}, 1 glow KEEP`);
}

const merged = mergeByMaterial(g, "apollonian");
writeFileSync("agents/arthur/assets/village_apollonian3.glb", toGLB(merged));
console.log(`wrote agents/arthur/assets/village_apollonian3.glb`);
